import re
from datetime import date

def extract_dates(text):
    found = []
    for d, m, y in re.findall(r"\b(\d{2})/(\d{2})/(\d{4})\b", text):
        try:
            found.append(date(int(y), int(m), int(d)))
        except ValueError:
            pass
    return found

