import csv, re

LINE = re.compile(r"(?P<stamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (?P<level>[A-Z]+) (?P<message>.+)")

def daily_report(log_path, out_path):
    counts = {}
    with open(log_path) as f:
        for line in f:
            m = LINE.fullmatch(line.strip())
            if m:
                day = m["stamp"][:10]
                counts[day] = counts.get(day, 0) + (m["level"] == "ERROR")
    with open(out_path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["date", "errors"])
        for day in sorted(counts):
            writer.writerow([day, counts[day]])

def week_summary(dates):
    weeks = {}
    for d in dates:
        week = d.isocalendar().week
        weeks[week] = weeks.get(week, 0) + 1
    return weeks
